+-- DATA-12: expand the email rename while old application code still runs.
+-- After all readers and writers use email_address, a later migration can
+-- remove email, this trigger, and its function.
+ALTER TABLE users ADD COLUMN email_address TEXT;
+
+UPDATE users SET email_address = email;
+
+ALTER TABLE users
+  ALTER COLUMN email_address SET NOT NULL,
+  ADD CONSTRAINT users_email_address_key UNIQUE (email_address);
+
+CREATE FUNCTION sync_users_email_address() RETURNS trigger
+LANGUAGE plpgsql AS $$
+BEGIN
+  IF TG_OP = 'INSERT' THEN
+    IF NEW.email_address IS NULL THEN
+      NEW.email_address := NEW.email;
+    ELSIF NEW.email IS NULL THEN
+      NEW.email := NEW.email_address;
+    END IF;
+  ELSE
+    IF NEW.email IS DISTINCT FROM OLD.email
+       AND NEW.email_address IS NOT DISTINCT FROM OLD.email_address THEN
+      NEW.email_address := NEW.email;
+    ELSIF NEW.email_address IS DISTINCT FROM OLD.email_address
+       AND NEW.email IS NOT DISTINCT FROM OLD.email THEN
+      NEW.email := NEW.email_address;
+    END IF;
+  END IF;
+
+  IF NEW.email IS DISTINCT FROM NEW.email_address THEN
+    RAISE EXCEPTION 'email and email_address must match'
+      USING ERRCODE = '23514';
+  END IF;
+
+  RETURN NEW;
+END;
+$$;
+
+CREATE TRIGGER users_sync_email_address
+BEFORE INSERT OR UPDATE ON users
+FOR EACH ROW EXECUTE FUNCTION sync_users_email_address();

