+  ALTER COLUMN email SET NOT NULL,
+  ADD CONSTRAINT users_legacy_email_key UNIQUE (email);
+
+CREATE FUNCTION users_sync_email_columns() RETURNS trigger
+LANGUAGE plpgsql AS $$
+BEGIN
+  IF TG_OP = 'INSERT' THEN
+    IF NEW.email_address IS NULL THEN
+      NEW.email_address := NEW.email;
+    ELSIF NEW.email IS NULL THEN
+      NEW.email := NEW.email_address;
+    ELSIF NEW.email IS DISTINCT FROM NEW.email_address THEN
+      RAISE EXCEPTION 'email and email_address must match'
+        USING ERRCODE = '23514';
+    END IF;
+  ELSE
+    IF NEW.email IS DISTINCT FROM OLD.email
+       AND NEW.email_address IS DISTINCT FROM OLD.email_address THEN
+      IF NEW.email IS DISTINCT FROM NEW.email_address THEN
+        RAISE EXCEPTION 'email and email_address must match'
+          USING ERRCODE = '23514';
